        <li><svg aria-hidden="true" focusable="false"><use href="#i-check"/></svg><span>50,000 responses/माह</span></li>
      </ul>
    </li>
  </ul>

  <!-- पेज load पर खाली रहता है; केवल user action पर भरा जाता है -->
  <p class="sr-only" role="status" data-status></p>
</section>

<script>
(() => {
  // Production में ये values billing API/config से आएँ, hardcode न करें।
  const PLANS = {
    starter:  { name: 'Starter',  monthly: 0,    annualMonthly: 0,    annualBill: 0 },
    // ⚠ BLOCKER (खुला प्रश्न #1): 789 × 12 = 9,468 ≠ 9,990. Pricing doc से as-is रखा है।
    pro:      { name: 'Pro',      monthly: 999,  annualMonthly: 789,  annualBill: 9990 },
    business: { name: 'Business', monthly: 2499, annualMonthly: 1999, annualBill: 23988 },
  };

  const fmt = new Intl.NumberFormat('en-IN');
  const rupee = n => `₹${fmt.format(n)}`;

  // Dev guard: वार्षिक कीमतें आपस में मेल न खाएँ तो चेतावनी दें
  Object.entries(PLANS).forEach(([id, p]) => {
    if (p.annualMonthly * 12 !== p.annualBill) {
      console.warn(`[pricing] ${id}: ${p.annualMonthly} × 12 = ${p.annualMonthly * 12} ≠ annualBill ${p.annualBill}`);
    }
  });

  const root   = document.querySelector('.pricing');
  const status = root.querySelector('[data-status]');
  const currentBilling = () => root.querySelector('input[name="billing"]:checked').value;

  function noteText(p, billing) {
    if (p.monthly === 0) return 'हमेशा मुफ़्त';                         // खुला प्रश्न #3
    return billing === 'annual'
      ? `${rupee(p.annualBill)} सालाना बिल किया जाएगा (+ GST)`
      : 'हर महीने बिल किया जाएगा (+ GST)';                              // प्रस्तावित copy, खुला प्रश्न #4
  }

  function render(billing, announce) {
    const spoken = [];
    root.querySelectorAll('[data-plan]').forEach(card => {
      const p = PLANS[card.dataset.plan];
      const price = billing === 'annual' ? p.annualMonthly : p.monthly;
      card.querySelector('[data-amount]').textContent = rupee(price);
      card.querySelector('[data-note]').textContent = noteText(p, billing);
      if (p.monthly > 0) {
        spoken.push(billing === 'annual'
          ? `${p.name} ${rupee(price)} प्रति माह, ${rupee(p.annualBill)} सालाना बिल`
          : `${p.name} ${rupee(price)} प्रति माह`);
      }
    });
    if (announce) {
      const label = billing === 'annual' ? 'वार्षिक' : 'मासिक';
      status.textContent = `${label} कीमतें: ${spoken.join('। ')}। GST अतिरिक्त।`;
    }
  }

  root.querySelectorAll('input[name="billing"]').forEach(radio =>
    radio.addEventListener('change', e => render(e.target.value, true)));

  // Server-rendered HTML को radio state से sync करें (bfcache/autofill)। यहाँ announcement नहीं होगा।
  render(currentBilling(), false);

  // ───────── CTA loading ─────────
  // `disabled` की जगह aria-disabled: focus button पर ही रहता है और SR उसे "dimmed/unavailable" बताता है।
  function setBusy(btn, busy) {
    busy ? btn.setAttribute('aria-disabled', 'true') : btn.removeAttribute('aria-disabled');
  }

  root.querySelectorAll('[data-cta]').forEach(btn => {
    btn.addEventListener('click', async () => {
      if (btn.getAttribute('aria-disabled') === 'true') return;   // double-submit रोकें
      const id = btn.closest('[data-plan]').dataset.plan;
      setBusy(btn, true);
      status.textContent = id === 'starter'
        ? 'खाता बनाया जा रहा है…'
        : `${PLANS[id].name} ट्रायल शुरू हो रहा है…`;
      try {
        await startCheckout(id, currentBilling());
      } catch {
        status.textContent = 'कुछ ग़लत हो गया। कृपया दोबारा कोशिश करें।';
      } finally {
        setBusy(btn, false);
      }
    });
  });

  // Demo stub: असली app में signup/checkout API call होगी
  function startCheckout(plan, billing) {
    return new Promise(resolve => setTimeout(resolve, 1500));
  }
})();
</script>
</body>
</html>
```

